fn find_smallest(s: &Vec<u32>) -> Option<u32> {
    // Check if the vector is empty
    if s.is_empty() {
        return None;
    }

    // Initialize the smallest element with the first element of the vector
    let mut smallest = s[0];

    // Iterate through the vector to find the smallest element
    for &value in s.iter() {
        if value < smallest {
            smallest = value;
        }
    }

    // Return the smallest element wrapped in Some
    Some(smallest)
}